#include "LoRa.h"
#include "cmsis_os.h"
// External handle to SPI2 generated by STM32CubeMX
extern SPI_HandleTypeDef hspi2;

/* Hardware Control Macros using CubeMX Labels */
#define LORA_CS_LOW()      HAL_GPIO_WritePin(LoRa_CS_GPIO_Port, LoRa_CS_Pin, GPIO_PIN_RESET)
#define LORA_CS_HIGH()     HAL_GPIO_WritePin(LoRa_CS_GPIO_Port, LoRa_CS_Pin, GPIO_PIN_SET)
#define LORA_RST_LOW()     HAL_GPIO_WritePin(LoRa_Rst_GPIO_Port, LoRa_Rst_Pin, GPIO_PIN_RESET)
#define LORA_RST_HIGH()    HAL_GPIO_WritePin(LoRa_Rst_GPIO_Port, LoRa_Rst_Pin, GPIO_PIN_SET)
#define LORA_READ_DIO0()   HAL_GPIO_ReadPin(LoRa_D100_GPIO_Port, LoRa_D100_Pin)

void LoRa_Reset(void)
{
    LORA_RST_LOW();
    HAL_Delay(10);
    LORA_RST_HIGH();
    HAL_Delay(10);
}

uint8_t LoRa_ReadRegister(uint8_t address)
{
    uint8_t tx = address & 0x7F; // Bit 7 = 0 for Read
    uint8_t rx = 0;

    LORA_CS_LOW();
    HAL_SPI_Transmit(&hspi2, &tx, 1, 100);
    HAL_SPI_Receive(&hspi2, &rx, 1, 100);
    LORA_CS_HIGH();

    return rx;
}

void LoRa_WriteRegister(uint8_t address, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(address | 0x80), value }; // Bit 7 = 1 for Write

    LORA_CS_LOW();
    HAL_SPI_Transmit(&hspi2, tx, 2, 100);
    LORA_CS_HIGH();
}

uint8_t LoRa_Init(void)
{
    LoRa_Reset();

    // 1. Verify silicon version (SX1276/78 returns 0x12)
    uint8_t version = LoRa_ReadRegister(REG_VERSION);
    if (version != 0x12) {
        return 0; // SPI failure or module unreachable
    }

    // 2. Put module to Sleep to enable LoRa mode
    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | MODE_SLEEP);

    // 3. Set Frequency to 433.0 MHz (Fx = (433000000 * 524288) / 32000000 = 0x6C8000)
    LoRa_WriteRegister(REG_FRF_MSB, 0x6C);
    LoRa_WriteRegister(REG_FRF_MID, 0x40);
    LoRa_WriteRegister(REG_FRF_LSB, 0x00);

    // 4. Set TX Power (+17 dBm via PA_BOOST)
    LoRa_WriteRegister(REG_PA_CONFIG, 0x8F);

    // 5. Modem Config: BW = 125 kHz, CR = 4/5, Explicit Header
    LoRa_WriteRegister(REG_MODEM_CONFIG_1, 0x72);

    // 6. Modem Config: SF = 7, CRC Enabled
    LoRa_WriteRegister(REG_MODEM_CONFIG_2, 0x74);

    // 7. AGC auto-on
    LoRa_WriteRegister(REG_MODEM_CONFIG_3, 0x04);

    // =========================================================
        // EXPLICITLY SET SYNC WORD TO 0x12 (Register 0x39)
        // =========================================================
        LoRa_WriteRegister(0x39, 0x12);

    // 8. Put in Standby mode
    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | MODE_STDBY);

    return 1; // Initialized successfully
}

uint8_t LoRa_Transmit(uint8_t *payload, uint8_t length)
{
	// 1. Enter Standby mode
	    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | MODE_STDBY);

	    // 2. Reset FIFO pointers to base address
	    LoRa_WriteRegister(REG_FIFO_TX_BASE_ADDR, 0x80);
	    LoRa_WriteRegister(REG_FIFO_ADDR_PTR, 0x80);

	    // 3. Load payload buffer into FIFO
	    for (uint8_t i = 0; i < length; i++) {
	        LoRa_WriteRegister(REG_FIFO, payload[i]);
	    }
	    LoRa_WriteRegister(REG_PAYLOAD_LENGTH, length);

	    // 4. Explicitly map DIO0 to TxDone (0x40)
	    LoRa_WriteRegister(0x40, 0x40);

	    // 5. Clear all IRQ flags before transmission
	    LoRa_WriteRegister(REG_IRQ_FLAGS, 0xFF);

	    // 6. Switch to TX mode to broadcast
	    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | MODE_TX);

	    // 7. Poll Bit 3 (TxDone = 0x08) in REG_IRQ_FLAGS with an adequate 1-second timeout
	    uint32_t timeout_count = 100; // 100 * 10ms = 1000ms timeout
	    while (((LoRa_ReadRegister(REG_IRQ_FLAGS) & 0x08) == 0) && (timeout_count > 0)) {
	        osDelay(10); // Yield to other FreeRTOS tasks
	        timeout_count--;
	    }

	    // 8. Clear IRQ flags and return to Standby
	    LoRa_WriteRegister(REG_IRQ_FLAGS, 0xFF);
	    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | MODE_STDBY);

	    return (timeout_count > 0) ? 1 : 0;
}

void LoRa_Sleep(void)
{
    // Bit 7: 1 = LoRa Mode (MODE_LONG_RANGE_MODE)
    // Bits 2-0: 000 = Sleep Mode (0x00)
    LoRa_WriteRegister(REG_OP_MODE, MODE_LONG_RANGE_MODE | 0x00);
}
